import heapq

class Solution:
    def lastStoneWeight(self, stones: List[int]) -> int:
        pq = [-s for s in stones]  # max-heap via negation
        heapq.heapify(pq)
        while len(pq) > 1:
            a, b = -heapq.heappop(pq), -heapq.heappop(pq)
            if a != b:
                heapq.heappush(pq, -(a - b))
        return -pq[0] if pq else 0
```

**Time/Space:** O(n log n) / O(n)

**Pitfall:** Forgetting the empty-heap case when all stones cancel out.

**Pattern:** Max-heap of size k

**Key insight:** Keep a max-heap by squared distance; evict the farthest once it exceeds k.

**Java**

```java
class Solution {
    public int[][] kClosest(int[][] points, int k) {
        PriorityQueue<int[]> pq = new PriorityQueue<>(
            (a, b) -> Integer.compare(b[0] * b[0] + b[1] * b[1], a[0] * a[0] + a[1] * a[1]));
        for (int[] p : points) {
            pq.offer(p);
            if (pq.size() > k) pq.poll();
        }
        return pq.toArray(new int[0][]);
    }
}
```

