        res, path = [], []

        def go(start: int, left: int) -> None:
            if left == 0:
                res.append(path[:])
                return
            for i in range(start, len(c)):
                if c[i] > left:
                    break
                path.append(c[i])
                go(i, left - c[i])
                path.pop()

        go(0, target)
        return res
