from collections import deque

class Solution:
    def wallsAndGates(self, rooms: List[List[int]]) -> None:
        INF = 2**31 - 1
        R, C = len(rooms), len(rooms[0])
        q = deque((r, c) for r in range(R) for c in range(C) if rooms[r][c] == 0)
        while q:
            pr, pc = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                r, c = pr + dr, pc + dc
                if 0 <= r < R and 0 <= c < C and rooms[r][c] == INF:
                    rooms[r][c] = rooms[pr][pc] + 1
                    q.append((r, c))
```

**Time/Space:** O(R·C) / O(R·C)

**Pitfall:** BFS from each gate separately is O((R·C)²); seed all gates together.

**Pattern:** Multi-source BFS by level

**Key insight:** Seed the queue with all rotten oranges and count fresh ones; each BFS level is one minute.

**Java**

```java
class Solution {
    public int orangesRotting(int[][] grid) {
        Deque<int[]> q = new ArrayDeque<>();
        int fresh = 0, minutes = 0;
        for (int r = 0; r < grid.length; r++)
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 2) q.add(new int[]{r, c});
                else if (grid[r][c] == 1) fresh++;
            }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty() && fresh > 0) {
            for (int k = q.size(); k > 0; k--) {
                int[] p = q.poll();
                for (int[] d : dirs) {
                    int r = p[0] + d[0], c = p[1] + d[1];
                    if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] != 1) continue;
                    grid[r][c] = 2; fresh--;
                    q.add(new int[]{r, c});
                }
            }
            minutes++;
        }
        return fresh == 0 ? minutes : -1;
    }
}
```

**Python**

```python
from collections import deque

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        q = deque()
        fresh = minutes = 0
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 2:
                    q.append((r, c))
                elif grid[r][c] == 1:
                    fresh += 1
        while q and fresh > 0:
            for _ in range(len(q)):
                pr, pc = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    r, c = pr + dr, pc + dc
                    if 0 <= r < R and 0 <= c < C and grid[r][c] == 1:
                        grid[r][c] = 2
                        fresh -= 1
                        q.append((r, c))
            minutes += 1
        return minutes if fresh == 0 else -1
```

**Time/Space:** O(R·C) / O(R·C)

**Pitfall:** Counting a minute for the final empty level overstates the answer by one — stop when fresh hits 0.

**Pattern:** Reverse DFS from each ocean

**Key insight:** Flow uphill from each ocean's border cells to mark what can reach it; answer is the intersection.

**Java**

```java
class Solution {
    public List<List<Integer>> pacificAtlantic(int[][] h) {
        int R = h.length, C = h[0].length;
        boolean[][] pac = new boolean[R][C], atl = new boolean[R][C];
        for (int r = 0; r < R; r++) { dfs(h, pac, r, 0, 0); dfs(h, atl, r, C - 1, 0); }
        for (int c = 0; c < C; c++) { dfs(h, pac, 0, c, 0); dfs(h, atl, R - 1, c, 0); }
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                if (pac[r][c] && atl[r][c]) res.add(List.of(r, c));
        return res;
    }
    private void dfs(int[][] h, boolean[][] seen, int r, int c, int prev) {
        if (r < 0 || c < 0 || r >= h.length || c >= h[0].length || seen[r][c] || h[r][c] < prev) return;
        seen[r][c] = true;
        dfs(h, seen, r + 1, c, h[r][c]); dfs(h, seen, r - 1, c, h[r][c]);
        dfs(h, seen, r, c + 1, h[r][c]); dfs(h, seen, r, c - 1, h[r][c]);
    }
}
```

**Python**

```python
class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        R, C = len(heights), len(heights[0])
        pac, atl = set(), set()

        def dfs(r: int, c: int, seen: set, prev: int) -> None:
            if (r < 0 or c < 0 or r >= R or c >= C or (r, c) in seen
                    or heights[r][c] < prev):
                return
            seen.add((r, c))
            h = heights[r][c]
            dfs(r + 1, c, seen, h); dfs(r - 1, c, seen, h)
            dfs(r, c + 1, seen, h); dfs(r, c - 1, seen, h)

        for r in range(R):
            dfs(r, 0, pac, 0)
            dfs(r, C - 1, atl, 0)
        for c in range(C):
            dfs(0, c, pac, 0)
            dfs(R - 1, c, atl, 0)
        return [[r, c] for r in range(R) for c in range(C) if (r, c) in pac and (r, c) in atl]
```

**Time/Space:** O(R·C) / O(R·C)

**Pitfall:** Running a forward search from every cell is O((R·C)²); search backwards from the oceans.

**Pattern:** Border DFS then sweep

**Key insight:** Mark Os reachable from the border as safe; then flip remaining Os to X and restore safe ones.

**Java**

```java
class Solution {
    public void solve(char[][] b) {
        int R = b.length, C = b[0].length;
        for (int r = 0; r < R; r++) { mark(b, r, 0); mark(b, r, C - 1); }
        for (int c = 0; c < C; c++) { mark(b, 0, c); mark(b, R - 1, c); }
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                b[r][c] = b[r][c] == 'S' ? 'O' : 'X';
    }
    private void mark(char[][] b, int r, int c) {
        if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || b[r][c] != 'O') return;
        b[r][c] = 'S';
        mark(b, r + 1, c); mark(b, r - 1, c); mark(b, r, c + 1); mark(b, r, c - 1);
    }
}
```

**Python**

```python
class Solution:
    def solve(self, board: List[List[str]]) -> None:
        R, C = len(board), len(board[0])

        def mark(r: int, c: int) -> None:
            if r < 0 or c < 0 or r >= R or c >= C or board[r][c] != "O":
                return
            board[r][c] = "S"
            mark(r + 1, c); mark(r - 1, c); mark(r, c + 1); mark(r, c - 1)

        for r in range(R):
            mark(r, 0)
            mark(r, C - 1)
        for c in range(C):
            mark(0, c)
            mark(R - 1, c)
        for r in range(R):
            for c in range(C):
                board[r][c] = "O" if board[r][c] == "S" else "X"
```

**Time/Space:** O(R·C) / O(R·C)

**Pitfall:** Trying to detect "surrounded" from the inside is error-prone; start from the border instead.

**Pattern:** Topological sort (Kahn's BFS)

**Key insight:** Repeatedly take courses with zero remaining prerequisites; if all get taken there is no cycle.

**Java**

```java
class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[numCourses];
        for (int[] p : prerequisites) { adj.get(p[1]).add(p[0]); indeg[p[0]]++; }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) q.add(i);
        int taken = 0;
        while (!q.isEmpty()) {
            int c = q.poll();
            taken++;
            for (int nx : adj.get(c)) if (--indeg[nx] == 0) q.add(nx);
        }
        return taken == numCourses;
    }
}
```

**Python**

```python
